mapper.select:
SELECT STL_NO, SELLER_ID, ORD_NO, ITEM_SEQ, STL_STAT
  FROM TB_STL
 WHERE ORD_NO   = #{ORD_NO}
   AND ITEM_SEQ = #{ITEM_SEQ}
   AND STL_STAT <> 'CNCL'

SELECT P.STL_PAY_NO, P.SELLER_ID, L.SELLER_NM, L.BIZ_NO, P.PAY_SCHD_DT, P.STL_CNT, P.PAY_AMT, P.PAY_STAT, DECODE(P.PAY_STAT, 'W', '지급대기', 'P', '지급완료', 'H', '지급보류', P.PAY_STAT) AS PAY_STAT_NM, TO_CHAR(P.PAY_DT, 'YYYYMMDD') AS PAY_DT, NVL(P.BANK_CD, L.BANK_CD) AS BANK_CD, NVL(P.STL_ACCT_NO, L.STL_ACCT_NO) AS STL_ACCT_NO, (SELECT NVL(SUM(H.STL_AMT), 0) FROM TB_STL H WHERE H.SELLER_ID = P.SELLER_ID AND H.PAY_SCHD_DT = P.PAY_SCHD_DT AND H.STL_STAT = 'HOLD') AS HOLD_AMT FROM TB_STL_PAY P JOIN TB_SELLER L ON L.SELLER_ID = P.SELLER_ID
AND P.PAY_SCHD_DT >= #{FROM_YMD} AND P.PAY_SCHD_DT <= #{TO_YMD} AND P.SELLER_ID = #{SELLER_ID} AND P.PAY_STAT = #{PAY_STAT}
ORDER BY P.PAY_SCHD_DT DESC, L.SELLER_NM
